(()=>{
  const dialog=document.querySelector('#plan-dialog'),money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n/100);let onSuccess=null;
  function price(){const form=dialog.querySelector('form'),n=Number(form.elements.studentLimit.value),split=form.elements.paymentOption.value==='installments',extra=Math.max(0,n-1000)*250,total=n<=350?(split?180000:160000):(split?280000:260000)+extra;dialog.querySelector('#plan-estimate').textContent=Number.isInteger(n)&&n>=1?money(total)+(split?' no total, em até 12x de aproximadamente '+money(Math.round(total/12)):' à vista')+(extra?' · inclui '+money(extra)+' por '+(n-1000)+' alunos excedentes':''):'Informe a quantidade de alunos para simular o plano.';}
  const field=(label,name,type='text',attrs='')=>`<div><label for="enroll-${name}">${label}</label><input id="enroll-${name}" name="${name}" type="${type}" ${attrs} required></div>`;
  function render(){dialog.innerHTML=`<div class="plan-dialog-header"><div><span>PARA ESCOLAS E INSTITUIÇÕES</span><h2>Sua escola ainda não tem plano?</h2><p>Escolha o plano e solicite a contratação do Conecta+.</p></div><button class="plan-close" type="button" aria-label="Fechar planos">×</button></div><div class="plan-price-cards"><article><span>ATÉ 350 ALUNOS</span><h3>Escola conectada</h3><strong>R$ 1.600<small>à vista</small></strong><p>Ou R$ 1.800 no total<br>em até 12x de R$ 150.</p></article><article class="featured"><span>DE 351 A 1.000 ALUNOS</span><h3>Mais conexões</h3><strong>R$ 2.600<small>à vista</small></strong><p>Ou R$ 2.800 no total<br>em até 12x de aproximadamente R$ 233,33.</p></article></div><p class="plan-extra">Mais de 1.000 alunos? Acrescente <strong>R$ 2,50 por aluno excedente</strong> ao plano de 1.000 alunos.</p><div class="plan-simulation-note">Demonstração sem pagamento. A solicitação será analisada pelo ADM antes da liberação da escola.</div><form id="plan-enrollment-form"><h3>Solicitar contratação</h3><div class="plan-fields">${field('Nome da escola','schoolName','text','minlength="2" maxlength="120"')}${field('Nome do responsável pela instituição','name','text','minlength="2" maxlength="120"')}${field('Crie o usuário de acesso da escola','login','text','minlength="3" maxlength="120" autocomplete="username"')}${field('Crie uma senha para a escola','password','password','minlength="8" maxlength="128" autocomplete="new-password"')}<div><label for="enroll-studentLimit">Quantidade de alunos / capacidade</label><input id="enroll-studentLimit" name="studentLimit" type="number" min="1" max="100000" step="1" value="350" required></div><div><label for="enroll-billingCycle">Ciclo da assinatura (visual)</label><select id="enroll-billingCycle" name="billingCycle" required><option value="annual">Anual</option><option value="monthly">Mensal</option></select></div><div><label for="enroll-paymentOption">Condição do plano (visual)</label><select id="enroll-paymentOption" name="paymentOption" required><option value="upfront">À vista</option><option value="installments">Em até 12x</option></select></div></div><div id="plan-estimate" class="plan-estimate" role="status"></div><p class="school-help">O cadastro cria apenas o acesso do gestor. Turmas e contas de professores, pais e alunos ficam disponíveis após a autorização do ADM.</p><p id="plan-request-status" role="status" aria-live="polite"></p><button class="school-button" type="submit">Solicitar contratação sem pagamento</button></form>`;price();}
  dialog.addEventListener('input',()=>{if(dialog.querySelector('form'))price();});dialog.addEventListener('change',()=>{if(dialog.querySelector('form'))price();});
  dialog.addEventListener('click',e=>{if(e.target.closest('.plan-close'))dialog.close();if(e.target.closest('[data-enter-school]')){const result=dialog._result;dialog.close();onSuccess?.(result);}});
  dialog.addEventListener('close',()=>{const password=dialog.querySelector('[name=password]');if(password)password.value='';});
  dialog.addEventListener('submit',async e=>{if(e.target.id!=='plan-enrollment-form')return;e.preventDefault();const form=e.target,values=Object.fromEntries(new FormData(form)),submit=form.querySelector('[type=submit]'),status=dialog.querySelector('#plan-request-status');submit.disabled=true;status.textContent='Enviando solicitação…';try{const response=await fetch('/api/institution-request',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)}),result=await response.json();if(!response.ok)throw Error(result.error||'Não foi possível enviar.');form.reset();dialog._result=result;form.innerHTML='<div class="plan-success"><span>Solicitação enviada</span><h3>Aguardando liberação do ADM</h3><p></p><button class="school-button" type="button" data-enter-school>Entrar e acompanhar minha solicitação</button></div>';form.querySelector('p').textContent=result.message;}catch(error){status.textContent=error.message;submit.disabled=false;}});
  window.ConectaPlans={open(callback){onSuccess=callback;render();dialog.showModal();}};
})();
